function fail(message) {
  throw new Error(message);
}

function sha256(value) {
  return crypto.createHash('sha256').update(value, 'utf8').digest('hex');
}

function validateOneStageArtifact(actual, expected, label) {
  if (!actual || typeof actual !== 'object' || Array.isArray(actual)) {
    fail(`stage_${label}_evidence_invalid`);
  }

  if (actual.path !== expected.path) {
    fail(`stage_${label}_path_mismatch`);
  }

  if (actual.sha256 !== expected.sha256) {
    fail(`stage_${label}_sha_mismatch`);
  }

  if (actual.exists !== true) {
    fail(`stage_${label}_missing`);
  }

  if (actual.regular !== true) {
    fail(`stage_${label}_not_regular`);
  }

  if (actual.symlink !== false) {
    fail(`stage_${label}_symlink_rejected`);
  }
}

function validateStageEvidence(evidence) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) {
    fail('stage_evidence_invalid');
  }

  validateOneStageArtifact(
    evidence.transport,
    STAGE_ARTIFACTS.transport,
    'transport'
  );

  validateOneStageArtifact(
    evidence.bootstrap,
    STAGE_ARTIFACTS.bootstrap,
    'bootstrap'
  );

  return true;
}

function baselineAnchor(baseline) {
  return (
    'const BASELINE=Object.freeze(' +
    JSON.stringify(baseline) +
    ');'
  );
}

function countOccurrences(source, needle) {
  let count = 0;
  let offset = 0;

  while (true) {
    const index = source.indexOf(needle, offset);
    if (index === -1) {
      return count;
    }

    count += 1;
    offset = index + needle.length;
  }
}

function buildCurrentBaselineCandidate(source) {
  if (typeof source !== 'string') {
    fail('baseline_source_invalid');
  }

  const oldAnchor = baselineAnchor(OLD_BASELINE);
  const currentAnchor = baselineAnchor(CURRENT_BASELINE);

  const oldCount = countOccurrences(source, oldAnchor);
  const currentCount = countOccurrences(source, currentAnchor);

  if (oldCount !== 1) {
    fail(
      oldCount === 0
        ? 'expected_old_baseline_missing'
        : 'expected_old_baseline_not_unique'
    );
  }

  if (currentCount !== 0) {
    fail('current_baseline_already_present');
  }

  const content = source.replace(oldAnchor, currentAnchor);

  if (countOccurrences(content, oldAnchor) !== 0) {
    fail('old_baseline_remains_after_refresh');
  }

  if (countOccurrences(content, currentAnchor) !== 1) {
    fail('current_baseline_postcondition_failed');
  }

  return Object.freeze({
    ok: true,
    content,
    sha256: sha256(content),
    replacement_count: 1,
    production_mutation: false,
  });
}


const PROMOTION_ACTION =
  'control_plane_typed_bootstrap_current_baseline_refresh_v1';

const PROMOTION_OPERATION =
  'host_action.control_plane_typed_bootstrap_current_baseline_refresh_v1';

const PROMOTION_SOURCE_SHA256 =
  'd3be569a4fd63b8e0c78e370ad689a27aa2751ea772891cb6b7ffe7fbd49b35e';

const PROMOTION_CANDIDATE_SHA256 =
  '0adb6e91b006458da56566c2cdb2a903f945357b5bcf286cef7e5ce9cfcf1535';

function registrationReplaceOnce(source, oldValue, newValue, label) {
  const count = countOccurrences(source, oldValue);

  if (count !== 1) {
    fail(`registration_anchor_${label}_${count}`);
  }

  return source.replace(oldValue, newValue);
}

function buildRegistrationCandidates(input) {
  if (
    !input ||
    typeof input !== 'object' ||
    Array.isArray(input) ||
    Object.keys(input).sort().join(',') !== 'base,exec,mcp,policy'
  ) {
    fail('registration_input_invalid');
  }

  for (const name of ['base', 'exec', 'mcp', 'policy']) {
    if (typeof input[name] !== 'string') {
      fail(`registration_${name}_invalid`);
    }

    if (input[name].includes(PROMOTION_ACTION)) {
      fail(`registration_${name}_already_present`);
    }
  }

  const baseOld =
    "  control_plane_typed_bootstrap_transport_v1: { operation: " +
    "'host_action.control_plane_typed_bootstrap_transport_v1', " +
    "rollback: 'host-action-v2:control-plane-typed-bootstrap-transport-v1:" +
    "journal-restore' },";

  const baseNew =
    baseOld +
    "\n  " +
    PROMOTION_ACTION +
    ": { operation: '" +
    PROMOTION_OPERATION +
    "', rollback: 'host-action-v2:" +
    PROMOTION_ACTION.replaceAll('_', '-') +
    ":staged-bootstrap-source-restore' },";

  const base = registrationReplaceOnce(
    input.base,
    baseOld,
    baseNew,
    'base_spec'
  );

  const execSpecOld =
    "  control_plane_typed_bootstrap_transport_v1:" +
    "{operation:'host_action.control_plane_typed_bootstrap_transport_v1'," +
    "kind:'control_plane_typed_bootstrap_transport_v1'},";

  const execSpecNew =
    execSpecOld +
    "\n  " +
    PROMOTION_ACTION +
    ":{operation:'" +
    PROMOTION_OPERATION +
    "',kind:'" +
    PROMOTION_ACTION +
    "'},";

  let exec = registrationReplaceOnce(
    input.exec,
    execSpecOld,
    execSpecNew,
    'exec_spec'
  );

  const execHelperAnchor =
    'const applyHostActionV2Original=applyHostActionV2;';

  const fixedHandler = [
    "const CONTROL_PLANE_CURRENT_BASELINE_REFRESH_SOURCE=" +
      "'/var/lib/prhm-agent-selfmaint-exec/root-of-trust-stage-v1/" +
      "bootstrap-host-actions-control-plane-typed-bootstrap-transport-v1.js';",

    "const CONTROL_PLANE_CURRENT_BASELINE_REFRESH_SOURCE_SHA=" +
      "'" + PROMOTION_SOURCE_SHA256 + "';",

    "const CONTROL_PLANE_CURRENT_BASELINE_REFRESH_CANDIDATE_SHA=" +
      "'" + PROMOTION_CANDIDATE_SHA256 + "';",

    "const CONTROL_PLANE_CURRENT_BASELINE_REFRESH_BACKUP_ROOT=" +
      "'/var/backups/prhm-current-baseline-refresh-v1';",

    "const CONTROL_PLANE_CURRENT_BASELINE_OLD=" +
      JSON.stringify(
        'const BASELINE=Object.freeze(' +
        JSON.stringify(OLD_BASELINE) +
        ');'
      ) +
      ";",

    "const CONTROL_PLANE_CURRENT_BASELINE_NEW=" +
      JSON.stringify(
        'const BASELINE=Object.freeze(' +
        JSON.stringify(CURRENT_BASELINE) +
        ');'
      ) +
      ";",

    "function applyControlPlaneTypedBootstrapCurrentBaselineRefreshV1(){" +

      "const crypto=require('node:crypto');" +
      "const path=require('node:path');" +
      "const cp=require('node:child_process');" +

      "const target=CONTROL_PLANE_CURRENT_BASELINE_REFRESH_SOURCE;" +

      "const st=fs.lstatSync(target);" +
      "if(st.isSymbolicLink()||!st.isFile())" +
      "throw new Error('current_baseline_refresh_target_not_regular');" +

      "if(fs.realpathSync(target)!==target)" +
      "throw new Error('current_baseline_refresh_realpath_mismatch');" +

      "const original=fs.readFileSync(target);" +

      "const sourceSha=crypto.createHash('sha256')" +
      ".update(original).digest('hex');" +

      "if(sourceSha!==CONTROL_PLANE_CURRENT_BASELINE_REFRESH_SOURCE_SHA)" +
      "throw new Error('current_baseline_refresh_source_sha_mismatch');" +

      "const source=original.toString('utf8');" +

      "const baselinePrefix='const BASELINE=Object.freeze(';" +

      "const count=(s,n)=>s.split(n).length-1;" +

      "if(count(source,baselinePrefix)!==1)" +
      "throw new Error('current_baseline_refresh_baseline_anchor_not_unique');" +

      "if(count(source,CONTROL_PLANE_CURRENT_BASELINE_OLD)!==1)" +
      "throw new Error('current_baseline_refresh_old_anchor_mismatch');" +

      "if(count(source,CONTROL_PLANE_CURRENT_BASELINE_NEW)!==0)" +
      "throw new Error('current_baseline_refresh_new_anchor_already_present');" +

      "const candidate=source.replace(" +
      "CONTROL_PLANE_CURRENT_BASELINE_OLD," +
      "CONTROL_PLANE_CURRENT_BASELINE_NEW);" +

      "if(count(candidate,CONTROL_PLANE_CURRENT_BASELINE_OLD)!==0)" +
      "throw new Error('current_baseline_refresh_old_anchor_remaining');" +

      "if(count(candidate,CONTROL_PLANE_CURRENT_BASELINE_NEW)!==1)" +
      "throw new Error('current_baseline_refresh_new_anchor_postcondition');" +

      "const candidateBytes=Buffer.from(candidate,'utf8');" +

      "const candidateSha=crypto.createHash('sha256')" +
      ".update(candidateBytes).digest('hex');" +

      "if(candidateSha!==CONTROL_PLANE_CURRENT_BASELINE_REFRESH_CANDIDATE_SHA)" +
      "throw new Error('current_baseline_refresh_candidate_sha_mismatch');" +

      "fs.mkdirSync(CONTROL_PLANE_CURRENT_BASELINE_REFRESH_BACKUP_ROOT," +
      "{recursive:true,mode:0o700});" +

      "const stamp=new Date().toISOString()" +
      ".replace(/[-:.TZ]/g,'').slice(0,14);" +

      "const backup=path.join(" +
      "CONTROL_PLANE_CURRENT_BASELINE_REFRESH_BACKUP_ROOT," +
      "'current_baseline_refresh_backup-'+stamp+'-'+process.pid+'.js');" +

      "fs.writeFileSync(backup,original,{mode:0o600,flag:'wx'});" +

      "const dir=path.dirname(target);" +
      "const tmp=path.join(dir,'.'+path.basename(target)+" +
      "'.current-baseline-'+process.pid+'-'+Date.now()+'.tmp');" +

      "let wrote=false;" +

      "try{" +

        "fs.writeFileSync(tmp,candidateBytes," +
        "{mode:st.mode&0o777,flag:'wx'});" +

        "fs.chownSync(tmp,st.uid,st.gid);" +
        "fs.chmodSync(tmp,st.mode&0o777);" +

        "const syntax=cp.spawnSync('/usr/local/bin/prhm-node'," +
        "['--check',tmp]," +
        "{encoding:'utf8',timeout:30000,maxBuffer:300000});" +

        "if(syntax.error||syntax.status!==0)" +
        "throw new Error('current_baseline_refresh_candidate_syntax_invalid');" +

        "fs.renameSync(tmp,target);" +
        "wrote=true;" +

        "const finalBytes=fs.readFileSync(target);" +
        "const finalSha=crypto.createHash('sha256')" +
        ".update(finalBytes).digest('hex');" +

        "if(finalSha!==CONTROL_PLANE_CURRENT_BASELINE_REFRESH_CANDIDATE_SHA)" +
        "throw new Error('current_baseline_refresh_postwrite_sha_mismatch');" +

        "return {" +
          "ok:true," +
          "schema_version:'prhm.host-action-result.v1'," +
          "action:'" + PROMOTION_ACTION + "'," +
          "source_sha256:sourceSha," +
          "candidate_sha256:candidateSha," +
          "backup_path:backup," +
          "production_mutation:true," +
          "database_mutation:false," +
          "rollback_performed:false" +
        "};" +

      "}catch(error){" +

        "try{if(fs.existsSync(tmp))fs.unlinkSync(tmp);}catch{}" +

        "if(wrote){" +
          "let rollbackError=null;" +
          "try{" +

            "const rb=path.join(dir,'.'+path.basename(target)+" +
            "'.rollback-'+process.pid+'-'+Date.now()+'.tmp');" +

            "fs.writeFileSync(rb,original," +
            "{mode:st.mode&0o777,flag:'wx'});" +

            "fs.chownSync(rb,st.uid,st.gid);" +
            "fs.chmodSync(rb,st.mode&0o777);" +
            "fs.renameSync(rb,target);" +

            "const rollbackSha=crypto.createHash('sha256')" +
            ".update(fs.readFileSync(target)).digest('hex');" +

            "if(rollbackSha!==CONTROL_PLANE_CURRENT_BASELINE_REFRESH_SOURCE_SHA)" +
            "throw new Error('current_baseline_refresh_rollback_sha_mismatch');" +

          "}catch(e){" +
            "rollbackError=String(e&&e.message||e);" +
          "}" +

          "if(rollbackError)" +
          "throw new Error(" +
          "'current_baseline_refresh_apply_failed_rollback_failed:'+" +
          "String(error&&error.message||error)+':'+rollbackError);" +

          "throw new Error(" +
          "'current_baseline_refresh_apply_failed_rolled_back:'+" +
          "String(error&&error.message||error));" +
        "}" +

        "throw error;" +
      "}" +
    "}"
  ].join('\n');

  exec = registrationReplaceOnce(
    exec,
    execHelperAnchor,
    fixedHandler + '\n' + execHelperAnchor,
    'exec_helper'
  );

  const dispatchOld =
    "if(action==='control_plane_typed_bootstrap_transport_v1')" +
    "return applyControlPlaneTypedBootstrapTransportV1();";

  const dispatchNew =
    "if(action==='" +
    PROMOTION_ACTION +
    "')return applyControlPlaneTypedBootstrapCurrentBaselineRefreshV1();" +
    dispatchOld;

  exec = registrationReplaceOnce(
    exec,
    dispatchOld,
    dispatchNew,
    'exec_dispatch'
  );

  let policy;

  try {
    policy = JSON.parse(input.policy);
  } catch {
    fail('registration_policy_json_invalid');
  }

  if (
    !policy ||
    typeof policy !== 'object' ||
    Array.isArray(policy) ||
    !policy.operations ||
    typeof policy.operations !== 'object' ||
    !Array.isArray(policy.typed_scopes)
  ) {
    fail('registration_policy_shape_invalid');
  }

  if (
    policy.operations[PROMOTION_OPERATION] ||
    policy.typed_scopes.some(
      x => x && x.action === PROMOTION_ACTION
    )
  ) {
    fail('registration_policy_already_present');
  }

  policy.operations[PROMOTION_OPERATION] = {
    level: 4,
    risk: 'critical',
    requires_second_confirmation: true,
    one_time_use: true,
    requested_approver: 'mohammad',
    expires_seconds: 180,
    policy_version:
      '2026-09-06.1-control-plane-current-baseline-refresh-v1',
    rollback_reference:
      'host-action-v2:control-plane-current-baseline-refresh-v1:' +
      'staged-bootstrap-source-restore'
  };

  policy.typed_scopes.push({
    tool: 'host_action_v2_apply',
    project: 'control_plane',
    environment: 'production',
    action: PROMOTION_ACTION,
    risk: 'critical',
    operation: PROMOTION_OPERATION,
    principals: [
      {
        principal_id: 'mohammad',
        roles: ['mcp-operator']
      }
    ]
  });

  const policyText = JSON.stringify(policy, null, 2) + '\n';

  const mcpOld =
    "'control_plane_typed_bootstrap_transport_v1',";

  const mcpNew =
    mcpOld +
    "\n'" +
    PROMOTION_ACTION +
    "',";

  const mcp = registrationReplaceOnce(
    input.mcp,
    mcpOld,
    mcpNew,
    'mcp_enum'
  );

  for (const [name, value] of Object.entries({
    base,
    exec,
    mcp,
    policy: policyText
  })) {
    if (countOccurrences(value, PROMOTION_ACTION) < 1) {
      fail(`registration_${name}_postcondition_missing`);
    }
  }

  return Object.freeze({
    ok: true,
    action: PROMOTION_ACTION,
    source_sha256: PROMOTION_SOURCE_SHA256,
    candidate_sha256: PROMOTION_CANDIDATE_SHA256,
    files: Object.freeze({
      base,
      exec,
      policy: policyText,
      mcp
    }),
    production_mutation: false
  });
}


const REGISTRATION_BASELINE_SHA256 = Object.freeze({
  base: 'a23b4fec52123f8ad484f31576281c2f1933f24a3c811cd98c28e764a292e315',
  exec: '451c5a4762a4c7a04d64d526a79cf6e86b0cf7c978c559cf303d874e0f08fc48',
  policy: '494e95e3173695407c84b6d082f09e57d971cb193518be813a53131cdb389a70',
  mcp: '597701ccc1a6c39d54aef9bd22d1c8732c88536e36e12251511a509bde439b46',
});

const REGISTRATION_CANDIDATE_SHA256 = Object.freeze({
  base: 'aa6f3ed4f682dd4f50f56483edad435fc05454310449a21e9bc7a412b57efb60',
  exec: '90df17530735b3b340c2bc5ea0b8826b22ee1a6a184bd6e8a491b070ff52941c',
  policy: 'fcaee257f33cfaf5035eb97ada018af3f9115df9ac7afbd5ba55ce5961913574',
  mcp: '5b5bfe6ec8ee867b3ecfd20328be522bd67040c1cbfc8e066c40a8f9114922cb',
});

const REGISTRATION_OWNER_PATHS = Object.freeze({
  base: '/opt/prhm-agent-selfmaint/server.js',
  exec: '/opt/prhm-agent-selfmaint-exec/server.js',
  policy: '/opt/prhm-company-control-plane/config/approval-policy.json',
  mcp: '/home/agent/ssh-mcp-server/src/plugins/hostActionsV2.js',
});

function buildRegistrationInstallerSource() {
  const live = {};

  for (const [name, file] of Object.entries(REGISTRATION_OWNER_PATHS)) {
    const st = fs.lstatSync(file);

    if (st.isSymbolicLink() || !st.isFile()) {
      fail(`registration_installer_owner_not_regular:${name}`);
    }

    if (fs.realpathSync(file) !== file) {
      fail(`registration_installer_owner_realpath_mismatch:${name}`);
    }

    const bytes = fs.readFileSync(file);
    const actual = crypto
      .createHash('sha256')
      .update(bytes)
      .digest('hex');

    if (actual !== REGISTRATION_BASELINE_SHA256[name]) {
      fail(`registration_installer_baseline_drift:${name}`);
    }

    live[name] = bytes.toString('utf8');
  }

  const built = buildRegistrationCandidates(live);

  if (!built || built.ok !== true || built.production_mutation !== false) {
    fail('registration_installer_candidate_build_invalid');
  }

  const candidateB64 = {};

  for (const name of ['base', 'exec', 'policy', 'mcp']) {
    const content = built.files[name];

    const actual = crypto
      .createHash('sha256')
      .update(content, 'utf8')
      .digest('hex');

    if (actual !== REGISTRATION_CANDIDATE_SHA256[name]) {
      fail(`registration_installer_candidate_sha_mismatch:${name}`);
    }

    candidateB64[name] =
      Buffer.from(content, 'utf8').toString('base64');
  }

  return `'use strict';

const fs=require('fs');
const path=require('path');
const cp=require('child_process');
const crypto=require('crypto');

const ACTION=
  'control_plane_current_baseline_refresh_registration_installer_v1';

const TARGET=
  'control_plane_typed_bootstrap_current_baseline_refresh_v1';

const RESULT=
  '/var/lib/prhm-agent-selfmaint-exec/' +
  'current-baseline-refresh-registration-v1/latest.json';

const BACKUP_ROOT=
  '/var/backups/prhm-current-baseline-refresh-registration-v1';

const FILES=${JSON.stringify(REGISTRATION_OWNER_PATHS)};

const BASELINE=${JSON.stringify(REGISTRATION_BASELINE_SHA256)};

const CANDIDATE=${JSON.stringify(REGISTRATION_CANDIDATE_SHA256)};

const CANDIDATE_B64=${JSON.stringify(candidateB64)};

const SERVICES=[
  'prhm-company-approval.service',
  'prhm-agent-selfmaint.service',
  'prhm-agent-selfmaint-exec.service',
  'prhm-agent-mcp.service'
];

function shaBuffer(buf){
  return crypto.createHash('sha256').update(buf).digest('hex');
}

function shaFile(file){
  return shaBuffer(fs.readFileSync(file));
}

function run(bin,args,timeout=120000){
  return cp.execFileSync(
    bin,
    args,
    {
      encoding:'utf8',
      stdio:['ignore','pipe','pipe'],
      timeout
    }
  ).trim();
}

function atomicWrite(file,buf,mode,uid,gid,suffix){
  const tmp=
    file+'.'+suffix+'-'+process.pid+'-'+Date.now()+'.tmp';

  fs.writeFileSync(
    tmp,
    buf,
    {
      mode,
      flag:'wx'
    }
  );

  fs.chownSync(tmp,uid,gid);
  fs.chmodSync(tmp,mode);
  fs.renameSync(tmp,file);
}

function restartAll(){
  for(const service of SERVICES){
    run(
      '/usr/bin/systemctl',
      ['restart',service],
      60000
    );
  }
}

function verifyServices(){
  for(const service of SERVICES){
    if(
      run(
        '/usr/bin/systemctl',
        ['is-active',service],
        20000
      )!=='active'
    ){
      throw new Error('service_not_active:'+service);
    }
  }
}

function main(){
  if(process.argv.length!==2){
    throw new Error('unexpected_arguments');
  }

  if(process.getuid && process.getuid()!==0){
    throw new Error('root_required');
  }

  const old={};
  const stat={};
  const next={};

  for(const name of Object.keys(FILES)){
    const file=FILES[name];

    const lst=fs.lstatSync(file);

    if(lst.isSymbolicLink() || !lst.isFile()){
      throw new Error('owner_not_regular:'+name);
    }

    if(fs.realpathSync(file)!==file){
      throw new Error('owner_realpath_mismatch:'+name);
    }

    const actual=shaFile(file);

    if(actual!==BASELINE[name]){
      throw new Error('baseline_drift:'+name);
    }

    old[name]=fs.readFileSync(file);
    stat[name]=fs.statSync(file);

    next[name]=Buffer.from(
      CANDIDATE_B64[name],
      'base64'
    );

    if(shaBuffer(next[name])!==CANDIDATE[name]){
      throw new Error('candidate_sha_mismatch:'+name);
    }
  }

  const stamp=
    new Date()
      .toISOString()
      .replace(/[:.]/g,'-');

  const backupDir=
    path.join(BACKUP_ROOT,stamp);

  fs.mkdirSync(
    backupDir,
    {
      recursive:true,
      mode:0o700
    }
  );

  for(const name of Object.keys(FILES)){
    fs.writeFileSync(
      path.join(backupDir,name+'.bak'),
      old[name],
      {
        mode:0o600,
        flag:'wx'
      }
    );
  }

  const candidateTmp={};

  try{
    for(const name of Object.keys(FILES)){
      const file=FILES[name];

      candidateTmp[name]=
        file+
        '.candidate-'+
        process.pid+
        '-'+
        name;

      fs.writeFileSync(
        candidateTmp[name],
        next[name],
        {
          mode:stat[name].mode&0o777,
          flag:'wx'
        }
      );

      fs.chownSync(
        candidateTmp[name],
        stat[name].uid,
        stat[name].gid
      );
    }

    for(const name of ['base','exec','mcp']){
      const checked=
        cp.spawnSync(
          '/usr/local/bin/prhm-node',
          ['--check',candidateTmp[name]],
          {
            encoding:'utf8',
            timeout:30000,
            maxBuffer:1000000
          }
        );

      if(checked.error || checked.status!==0){
        throw new Error('syntax:'+name);
      }
    }

    JSON.parse(
      fs.readFileSync(
        candidateTmp.policy,
        'utf8'
      )
    );

    const mutated=[];

    try{
      for(const name of ['base','exec','policy','mcp']){
        fs.renameSync(
          candidateTmp[name],
          FILES[name]
        );

        mutated.push(name);

        if(shaFile(FILES[name])!==CANDIDATE[name]){
          throw new Error(
            'post_rename_sha_mismatch:'+name
          );
        }
      }

      restartAll();
      verifyServices();

      for(const name of Object.keys(FILES)){
        if(shaFile(FILES[name])!==CANDIDATE[name]){
          throw new Error(
            'post_install_sha_mismatch:'+name
          );
        }
      }

      const result={
        ok:true,
        schema_version:'prhm.host-action-result.v1',
        action:ACTION,
        target_action:TARGET,
        installed:true,
        production_mutation:true,
        database_mutation:false,
        rollback_performed:false,
        backup_dir:backupDir,
        post_install_sha256:
          Object.fromEntries(
            Object.keys(FILES).map(
              name=>[name,shaFile(FILES[name])]
            )
          )
      };

      fs.mkdirSync(
        path.dirname(RESULT),
        {
          recursive:true,
          mode:0o700
        }
      );

      atomicWrite(
        RESULT,
        Buffer.from(
          JSON.stringify(result,null,2)+'\\n'
        ),
        0o600,
        0,
        0,
        'result'
      );

      console.log(JSON.stringify(result));
      return;
    }catch(error){
      let rollbackError=null;

      for(const name of mutated.reverse()){
        try{
          atomicWrite(
            FILES[name],
            old[name],
            stat[name].mode&0o777,
            stat[name].uid,
            stat[name].gid,
            'rollback'
          );

          if(shaFile(FILES[name])!==BASELINE[name]){
            throw new Error(
              'rollback_sha_mismatch:'+name
            );
          }
        }catch(e){
          rollbackError=
            rollbackError ||
            String(e&&e.message||e);
        }
      }

      try{
        restartAll();
        verifyServices();
      }catch(e){
        rollbackError=
          rollbackError ||
          String(e&&e.message||e);
      }

      if(rollbackError){
        throw new Error(
          'install_failed_and_rollback_failed:'+
          String(error&&error.message||error)+
          ':'+
          rollbackError
        );
      }

      throw new Error(
        'install_failed_rolled_back:'+
        String(error&&error.message||error)
      );
    }
  }finally{
    for(const file of Object.values(candidateTmp)){
      try{
        if(file && fs.existsSync(file)){
          fs.unlinkSync(file);
        }
      }catch{}
    }
  }
}

try{
  main();
}catch(error){
  console.error(String(error&&error.stack||error));
  process.exit(1);
}
`;
}



const REGISTRATION_STAGE_TRANSPORT_ACTION =
  'control_plane_current_baseline_refresh_registration_installer_stage_v1';

const REGISTRATION_INSTALLER_SOURCE_SHA256 =
  "f72d40820188da43746ba5759ce9e9e7f3e811c0f3c1739a732cef9a78366f82";

const REGISTRATION_INSTALLER_DESTINATION =
  '/opt/prhm-agent-selfmaint-exec/actions/' +
  'current-baseline-refresh-registration-installer-v1.js';

function buildRegistrationStageTransportSource() {
  const INSTALLER_B64 =
    "";

  const INSTALLER_SHA =
    "f72d40820188da43746ba5759ce9e9e7f3e811c0f3c1739a732cef9a78366f82";

  return `'use strict';

const fs=require('node:fs');
const path=require('node:path');
const cp=require('node:child_process');
const crypto=require('node:crypto');

const ACTION=
  'control_plane_current_baseline_refresh_registration_installer_stage_v1';

const DESTINATION=
  '/opt/prhm-agent-selfmaint-exec/actions/current-baseline-refresh-registration-installer-v1.js';

const INSTALLER_SHA=
  '${INSTALLER_SHA}';

const INSTALLER_B64=
  '${INSTALLER_B64}';

const BACKUP_ROOT=
  '/var/backups/prhm-current-baseline-refresh-registration-installer-stage-v1';

function fail(code){
  throw new Error(code);
}

function digest(bytes){
  return crypto
    .createHash('sha256')
    .update(bytes)
    .digest('hex');
}

function assertRegularExact(file,label){
  const st=fs.lstatSync(file);

  if(st.isSymbolicLink() || !st.isFile()){
    fail(label+'_not_regular');
  }

  if(fs.realpathSync(file)!==file){
    fail(label+'_realpath_mismatch');
  }

  return st;
}

function installerBytes(){
  const bytes=
    Buffer.from(
      INSTALLER_B64,
      'base64'
    );

  const actual=
    digest(bytes);

  if(actual!==INSTALLER_SHA){
    fail(
      'source_sha_mismatch:'+
      actual
    );
  }

  const checked=
    cp.spawnSync(
      '/usr/local/bin/prhm-node',
      ['--check','-'],
      {
        input:bytes,
        encoding:null,
        timeout:30000,
        maxBuffer:1000000,
        env:{
          PATH:
            '/usr/local/sbin:/usr/local/bin:'+
            '/usr/sbin:/usr/bin:/sbin:/bin',
          LC_ALL:'C',
          HOME:'/nonexistent'
        }
      }
    );

  if(
    checked.error ||
    checked.status!==0
  ){
    fail(
      'candidate_sha_mismatch:'+
      'installer_syntax_invalid'
    );
  }

  return bytes;
}

function destinationState(){
  if(!fs.existsSync(DESTINATION)){
    return {
      exists:false,
      stat:null,
      bytes:null,
      sha256:null
    };
  }

  const st=
    assertRegularExact(
      DESTINATION,
      'destination'
    );

  const bytes=
    fs.readFileSync(DESTINATION);

  return {
    exists:true,
    stat:st,
    bytes,
    sha256:digest(bytes)
  };
}

function atomicWrite(
  file,
  bytes,
  mode,
  uid,
  gid,
  suffix
){
  const dir=
    path.dirname(file);

  const tmp=
    path.join(
      dir,
      '.'+
      path.basename(file)+
      '.'+
      suffix+
      '-'+
      process.pid+
      '-'+
      Date.now()+
      '.tmp'
    );

  let fd;

  try{
    fd=
      fs.openSync(
        tmp,
        'wx',
        mode
      );

    fs.writeFileSync(
      fd,
      bytes
    );

    fs.fsyncSync(fd);
    fs.closeSync(fd);
    fd=undefined;

    fs.chmodSync(
      tmp,
      mode
    );

    fs.chownSync(
      tmp,
      uid,
      gid
    );

    fs.renameSync(
      tmp,
      file
    );
  }catch(error){
    try{
      if(fd!==undefined){
        fs.closeSync(fd);
      }
    }catch{}

    try{
      if(fs.existsSync(tmp)){
        fs.unlinkSync(tmp);
      }
    }catch{}

    throw error;
  }
}

function preflight(){
  const candidate=
    installerBytes();

  const before=
    destinationState();

  return {
    ok:true,
    schema_version:
      'prhm.registration-installer-stage-preflight.v1',
    action:ACTION,
    preflight_only:true,
    candidate_sha256:
      digest(candidate),
    destination:
      DESTINATION,
    destination_exists:
      before.exists,
    destination_sha256:
      before.sha256,
    arbitrary_path:false,
    arbitrary_command:false,
    external_network:false,
    production_owner_mutation:false,
    database_mutation:false,
    production_mutation:false
  };
}

function apply(){
  if(
    process.getuid &&
    process.getuid()!==0
  ){
    fail('root_required');
  }

  const candidate=
    installerBytes();

  const before=
    destinationState();

  const parent=
    path.dirname(
      DESTINATION
    );

  const parentStat=
    fs.statSync(parent);

  const mode=
    before.exists
      ? before.stat.mode&0o777
      : 0o700;

  const uid=
    before.exists
      ? before.stat.uid
      : parentStat.uid;

  const gid=
    before.exists
      ? before.stat.gid
      : parentStat.gid;

  const stamp=
    new Date()
      .toISOString()
      .replace(
        /[-:.TZ]/g,
        ''
      )
      .slice(0,14);

  const backupDir=
    path.join(
      BACKUP_ROOT,
      stamp+
      '-'+
      process.pid
    );

  fs.mkdirSync(
    backupDir,
    {
      recursive:true,
      mode:0o700
    }
  );

  let backupPath=null;

  if(before.exists){
    backupPath=
      path.join(
        backupDir,
        'current-baseline-refresh-registration-installer-v1.js.bak'
      );

    fs.writeFileSync(
      backupPath,
      before.bytes,
      {
        mode:0o600,
        flag:'wx'
      }
    );
  }

  let wrote=false;

  try{
    atomicWrite(
      DESTINATION,
      candidate,
      mode,
      uid,
      gid,
      'stage'
    );

    wrote=true;

    assertRegularExact(
      DESTINATION,
      'destination_postwrite'
    );

    const finalSha=
      digest(
        fs.readFileSync(
          DESTINATION
        )
      );

    if(
      finalSha!==
      INSTALLER_SHA
    ){
      fail(
        'installer_sha_mismatch:'+
        finalSha
      );
    }

    const checked=
      cp.spawnSync(
        '/usr/local/bin/prhm-node',
        [
          '--check',
          DESTINATION
        ],
        {
          encoding:'utf8',
          timeout:30000,
          maxBuffer:1000000
        }
      );

    if(
      checked.error ||
      checked.status!==0
    ){
      fail(
        'postwrite_installer_syntax_invalid'
      );
    }

    return {
      ok:true,
      schema_version:
        'prhm.registration-installer-stage-result.v1',
      action:ACTION,
      status:'succeeded',
      destination:
        DESTINATION,
      old_sha256:
        before.sha256,
      new_sha256:
        finalSha,
      backup_path:
        backupPath,
      arbitrary_path:false,
      arbitrary_command:false,
      external_network:false,
      production_owner_mutation:false,
      database_mutation:false,
      production_mutation:true,
      rollback_performed:false
    };
  }catch(error){
    let rollbackError=null;

    if(wrote){
      try{
        if(before.exists){
          atomicWrite(
            DESTINATION,
            before.bytes,
            before.stat.mode&0o777,
            before.stat.uid,
            before.stat.gid,
            'rollback'
          );

          if(
            digest(
              fs.readFileSync(
                DESTINATION
              )
            )!==
            before.sha256
          ){
            fail(
              'rollback_sha_mismatch'
            );
          }
        }else{
          if(
            fs.existsSync(
              DESTINATION
            )
          ){
            fs.unlinkSync(
              DESTINATION
            );
          }
        }
      }catch(e){
        rollbackError=
          String(
            e &&
            e.message ||
            e
          );
      }
    }

    if(rollbackError){
      fail(
        'stage_failed_rollback_failed:'+
        String(
          error &&
          error.message ||
          error
        )+
        ':'+
        rollbackError
      );
    }

    fail(
      'stage_failed_rolled_back:'+
      String(
        error &&
        error.message ||
        error
      )
    );
  }
}

function main(){
  const args=
    process.argv.slice(2);

  if(
    args.length!==1 ||
    ![
      '--preflight-only',
      '--apply'
    ].includes(args[0])
  ){
    fail(
      'unexpected_arguments'
    );
  }

  const result=
    args[0]===
    '--preflight-only'
      ? preflight()
      : apply();

  process.stdout.write(
    JSON.stringify(
      result
    )+
    '\\n'
  );
}

module.exports={
  ACTION,
  DESTINATION,
  INSTALLER_SHA,
  preflight,
  apply
};

if(
  require.main===
  module
){
  try{
    main();
  }catch(error){
    console.error(
      JSON.stringify({
        ok:false,
        action:ACTION,
        error:String(
          error &&
          error.message ||
          error
        )
      })
    );

    process.exit(1);
  }
}
`;
}

module.exports = Object.freeze({
  ACTION,
  REGISTRATION_STAGE_TRANSPORT_ACTION,
  REGISTRATION_INSTALLER_SOURCE_SHA256,
  REGISTRATION_INSTALLER_DESTINATION,
  buildRegistrationStageTransportSource,
  REGISTRATION_BASELINE_SHA256,
  REGISTRATION_CANDIDATE_SHA256,
  buildRegistrationInstallerSource,
  PROMOTION_ACTION,
  PROMOTION_OPERATION,
  PROMOTION_SOURCE_SHA256,
  PROMOTION_CANDIDATE_SHA256,
  STAGE_ARTIFACTS,
  OLD_BASELINE,
  CURRENT_BASELINE,
  validateStageEvidence,
  buildCurrentBaselineCandidate,
  buildRegistrationCandidates,
});
